const { useEffect, useLayoutEffect, useRef, useState } = React;

const MIN = { w: 60, h: 40 };
const MAX = { w: 360, h: 200 };
const clamp = (value, min, max) => Math.min(max, Math.max(min, value));

const STYLE = `
  @scope {
    .cb-box { width: var(--w); height: var(--h); }
    .cb-stripe {
      width: hypot(var(--w), var(--h));
      height: 2px;
      transform-origin: top left;
      transform: rotate(atan2(var(--h), var(--w)));
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
`;

const Slider = ({ label, value, min, max, onChange }) => (
  <label className="flex min-w-[200px] flex-1 items-center gap-3">
    <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">{label}</span>
    <input
      type="range"
      min={min}
      max={max}
      value={value}
      onChange={(event) => onChange(Number(event.target.value))}
      className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
    />
    <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{value}px</span>
  </label>
);

const Component = () => {
  const stripeRef = useRef(null);
  const dragRef = useRef(null);
  const [w, setW] = useState(200);
  const [h, setH] = useState(120);
  const [cssLength, setCssLength] = useState(null);

  // 读出 CSS 算出的对角线宽度（计算值不受 rotate 影响），与 JS 结果对照
  useLayoutEffect(() => {
    setCssLength(parseFloat(getComputedStyle(stripeRef.current).width) || null);
  }, [w, h]);

  // 拖动右下角手柄调整宽高
  useEffect(() => {
    const move = (event) => {
      const drag = dragRef.current;
      if (!drag) return;
      setW(Math.round(clamp(drag.w + event.clientX - drag.x, MIN.w, MAX.w)));
      setH(Math.round(clamp(drag.h + event.clientY - drag.y, MIN.h, MAX.h)));
    };
    const stop = () => {
      dragRef.current = null;
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", stop);
    return () => {
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", stop);
    };
  }, []);

  const startDrag = (event) => {
    event.preventDefault();
    dragRef.current = { x: event.clientX, y: event.clientY, w, h };
  };

  const jsLength = Math.hypot(w, h);
  const angle = (Math.atan2(h, w) * 180) / Math.PI;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="overflow-x-auto rounded-tau-md border border-line-1 pb-8 pl-4 pr-14 pt-4">
        <div className="cb-box relative border border-dashed border-ink-3" style={{ "--w": `${w}px`, "--h": `${h}px` }}>
          <div ref={stripeRef} className="cb-stripe absolute left-0 top-0 rounded-full bg-accent" />
          <span className="absolute left-1/2 top-full mt-1 -translate-x-1/2 font-tau-mono text-tau-tiny text-ink-3">{w}px</span>
          <span className="absolute left-full top-1/2 ml-1.5 -translate-y-1/2 font-tau-mono text-tau-tiny text-ink-3">{h}px</span>
          <span className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-full rounded-tau-sm bg-surface px-1.5 font-tau-mono text-tau-sm text-accent-text shadow-card">
            {jsLength.toFixed(1)}px
          </span>
          <button
            type="button"
            aria-label="拖动调整宽高"
            onPointerDown={startDrag}
            className="absolute -bottom-2 -right-2 size-4 cursor-nwse-resize touch-none rounded-full border-2 border-accent bg-surface shadow-card"
          />
        </div>
      </div>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(200px,40%)]">
        <pre className="m-0 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
          <div>
            .box {"{"} --w: {w}px; --h: {h}px; {"}"}
          </div>
          <div>.stripe {"{"}</div>
          <div>
            {"  "}width: <span className="text-accent-text">hypot</span>(var(--w), var(--h));
          </div>
          <div>
            {"  "}transform: rotate(<span className="text-accent-text">atan2</span>(var(--h), var(--w)));
          </div>
          <div>{"}"}</div>
        </pre>
        <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 h-fit rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
          <dt className="text-ink-3">CSS hypot()</dt>
          <dd className="m-0 font-tau-mono text-ink-1">{cssLength ? `${cssLength.toFixed(2)}px` : "—"}</dd>
          <dt className="text-ink-3">Math.hypot</dt>
          <dd className="m-0 font-tau-mono text-ink-1">{jsLength.toFixed(2)}px</dd>
          <dt className="text-ink-3">旋转角度</dt>
          <dd className="m-0 font-tau-mono text-ink-1">{angle.toFixed(1)}deg</dd>
        </dl>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <Slider label="--w" value={w} min={MIN.w} max={MAX.w} onChange={setW} />
        <Slider label="--h" value={h} min={MIN.h} max={MAX.h} onChange={setH} />
      </div>
    </div>
  );
};

