const { useEffect, useRef, useState } = React;

const STYLE = `
  @scope {
    .cb-field {
      --cb-near: hypot(var(--cb-mx), var(--cb-my));
    }
    .cb-target {
      transition: scale 300ms var(--tau-ease-out), background-color 300ms var(--tau-ease-out), border-color 300ms var(--tau-ease-out);
    }
    @container style(--cb-near < var(--cb-limit)) {
      .cb-target {
        scale: 1.06;
        background-color: var(--tau-accent-soft);
        border-color: var(--tau-accent);
      }
    }
    .cb-range { accent-color: var(--tau-accent); }
  }
  @property --cb-mx { syntax: "<length>"; inherits: true; initial-value: 9999px; }
  @property --cb-my { syntax: "<length>"; inherits: true; initial-value: 0px; }
  @property --cb-near { syntax: "<length>"; inherits: true; initial-value: 9999px; }
  @property --cb-limit { syntax: "<length>"; inherits: true; initial-value: 120px; }
`;

const Component = () => {
  const fieldRef = useRef(null);
  const targetRef = useRef(null);
  const [limit, setLimit] = useState(120);
  const [pointer, setPointer] = useState(null);

  useEffect(() => {
    const field = fieldRef.current;
    const target = targetRef.current;
    // 把指针相对目标中心的偏移写进自定义属性，距离判断交给 CSS
    const move = event => {
      const rect = target.getBoundingClientRect();
      const fieldRect = field.getBoundingClientRect();
      const x = Math.round(event.clientX - rect.left - rect.width / 2);
      const y = Math.round(event.clientY - rect.top - rect.height / 2);
      field.style.setProperty("--cb-mx", `${x}px`);
      field.style.setProperty("--cb-my", `${y}px`);
      setPointer({
        x,
        y,
        cx: rect.left + rect.width / 2 - fieldRect.left,
        cy: rect.top + rect.height / 2 - fieldRect.top,
      });
    };
    const leave = () => {
      field.style.setProperty("--cb-mx", "9999px");
      field.style.setProperty("--cb-my", "0px");
      setPointer(null);
    };
    field.addEventListener("pointermove", move);
    field.addEventListener("pointerleave", leave);
    return () => {
      field.removeEventListener("pointermove", move);
      field.removeEventListener("pointerleave", leave);
    };
  }, []);

  const distance = pointer ? Math.hypot(pointer.x, pointer.y) : null;
  const near = distance !== null && distance < limit;

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div
          ref={fieldRef}
          className="cb-field relative grid h-[280px] min-w-0 cursor-crosshair touch-none place-items-center overflow-hidden rounded-tau-md border border-line-1"
          style={{ "--cb-limit": `${limit}px` }}
        >
          <div
            className="pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-full border border-dashed border-ink-3"
            style={{ width: limit * 2, height: limit * 2 }}
          />
          <div
            ref={targetRef}
            className="cb-target pointer-events-none relative grid h-20 w-32 place-items-center rounded-tau-sm border border-line-1 bg-surface shadow-card"
          >
            <span className="font-tau-mono text-tau-title text-ink-1">{distance === null ? "—" : `${Math.round(distance)}px`}</span>
          </div>
          {pointer && (
            <svg className="pointer-events-none absolute inset-0 size-full overflow-visible">
              <line
                x1={pointer.cx}
                y1={pointer.cy}
                x2={pointer.cx + pointer.x}
                y2={pointer.cy + pointer.y}
                className={near ? "stroke-accent" : "stroke-ink-3"}
                strokeWidth={1.5}
                strokeDasharray="4 3"
              />
              <circle cx={pointer.cx + pointer.x} cy={pointer.cy + pointer.y} r={4} className={near ? "fill-accent" : "fill-ink-3"} />
            </svg>
          )}
          {!pointer && (
            <span className="pointer-events-none absolute bottom-3 text-tau-sm text-ink-3">把指针移入这个区域</span>
          )}
        </div>
        <div className="flex min-w-0 flex-col gap-2">
          <pre className="m-0 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
            <div>.field {"{"}</div>
            <div>
              {"  "}--near: <span className="text-accent-text">hypot</span>(var(--m-x), var(--m-y));
            </div>
            <div>{"  "}--limit: {limit}px;</div>
            <div>{"}"}</div>
            <div className={`rounded-tau-sm px-1 transition-colors ${near ? "bg-accent-soft text-accent-text" : ""}`}>
              @container style(--near &lt; var(--limit)) {"{ … }"}
            </div>
          </pre>
          <dl className="m-0 grid grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-1.5 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
            <dt className="text-ink-3">--m-x</dt>
            <dd className="m-0 font-tau-mono text-ink-1">{pointer ? `${pointer.x}px` : "—"}</dd>
            <dt className="text-ink-3">--m-y</dt>
            <dd className="m-0 font-tau-mono text-ink-1">{pointer ? `${pointer.y}px` : "—"}</dd>
            <dt className="text-ink-3">--near</dt>
            <dd className="m-0 font-tau-mono text-ink-1">{distance === null ? "—" : `${distance.toFixed(1)}px`}</dd>
            <dt className="text-ink-3">查询结果</dt>
            <dd className="m-0">
              <span className={`rounded-tau-sm px-1.5 py-0.5 ${near ? "bg-ok-soft text-ok" : "text-ink-3"}`}>{near ? "命中，高亮" : "未命中"}</span>
            </dd>
          </dl>
        </div>
      </div>
      <label className="flex items-center gap-3">
        <span className="shrink-0 font-tau-mono text-tau-sm text-ink-2">--limit</span>
        <input
          type="range"
          min={60}
          max={160}
          value={limit}
          onChange={event => setLimit(Number(event.target.value))}
          className="cb-range h-1.5 min-w-0 flex-1 cursor-pointer"
        />
        <span className="w-14 shrink-0 text-right font-tau-mono text-tau-sm text-ink-1">{limit}px</span>
      </label>
    </div>
  );
};
